// === ESTRUCTURA DEL PATRÓN DECORATOR ===

// 1. Componente (interfaz común)
interface Beverage {
  getCost(): number;
  getDescription(): string;
}

// 2. Componentes Concretos (las bases)
class Espresso implements Beverage {
  getCost() { return 1.50; }
  getDescription() { return 'Espresso'; }
}

class HouseBlend implements Beverage {
  getCost() { return 0.89; }
  getDescription() { return 'House Blend Coffee'; }
}

// 3. Decorador Abstracto (la base para los extras)
abstract class BeverageDecorator implements Beverage {
  constructor(protected beverage: Beverage) {}

  abstract getCost(): number;
  abstract getDescription(): string;
}

// 4. Decoradores Concretos (los extras)
class Milk extends BeverageDecorator {
  getCost() { return this.beverage.getCost() + 0.20; }
  getDescription() { return this.beverage.getDescription() + ', Leche'; }
}

class Mocha extends BeverageDecorator {
  getCost() { return this.beverage.getCost() + 0.30; }
  getDescription() { return this.beverage.getDescription() + ', Chocolate'; }
}

class Whip extends BeverageDecorator {
  getCost() { return this.beverage.getCost() + 0.15; }
  getDescription() { return this.beverage.getDescription() + ', Crema'; }
}

// Uso — capas dinámicas:
let beverage: Beverage = new Espresso();
beverage = new Milk(beverage);      // Espresso + Leche
beverage = new Mocha(beverage);     // Espresso + Leche + Chocolate
beverage = new Whip(beverage);      // Espresso + Leche + Chocolate + Crema

console.log(beverage.getDescription()); // Espresso, Leche, Chocolate, Crema
console.log(beverage.getCost());        // 2.15

