// Explosión de subclases — cada combinación es una clase
class EspressoWithMilk extends Espresso {
  getCost() { return super.getCost() + 0.20; }
  getDescription() { return 'Espresso con Leche'; }
}

class EspressoWithMocha extends Espresso {
  getCost() { return super.getCost() + 0.30; }
  getDescription() { return 'Espresso con Chocolate'; }
}

class EspressoWithMilkAndMocha extends Espresso {
  getCost() { return super.getCost() + 0.50; }
  getDescription() { return 'Espresso con Leche y Chocolate'; }
}
// Cada combinación nueva = nueva subclase

codeAfter:
// Decorators apilables — combinaciones dinámicas
let beverage: Beverage = new Espresso();
beverage = new Milk(beverage);      // +$0.20
beverage = new Mocha(beverage);     // +$0.30

console.log(beverage.getDescription()); // Espresso, Leche, Chocolate
console.log(beverage.getCost());        // 2.00

// Agregá Crema en tiempo de ejecución
beverage = new Whip(beverage);      // +$0.15
console.log(beverage.getCost());        // 2.15

